<?php
namespace App\Http\Controllers;use App\Models\Company;use Illuminate\Http\Request;class CompanyController extends Controller{function index(){return view('refs.index',['title'=>'Companies','items'=>Company::paginate(30),'route'=>'companies']);}function create(){return view('refs.form',['item'=>new Company,'route'=>'companies']);}function store(Request $r){Company::create($r->validate(['name'=>'required','status'=>'nullable','type'=>'nullable','remarks'=>'nullable']));return redirect()->route('companies.index');}function edit(Company $company){return view('refs.form',['item'=>$company,'route'=>'companies']);}function update(Request $r,Company $company){$company->update($r->all());return redirect()->route('companies.index');}function destroy(Company $company){$company->delete();return back();}}
